#!/usr/bin/env python3
"""train_nrr.py - train the in-house upscaler on pairs generated by gen_training_pairs.py.

Why this exists: models/nrr_upscaler_v0.1.onnx is a skeleton whose refinement output is zero, so it is
an identity-preserving bilinear upsample with no learned weights. This is the first model in the
repository whose weights come from data we own and whose quality is measured against the baseline it
has to beat.

What is trained: a small 2x upscaler - feature extraction, depth and motion fusion, PixelShuffle
upsampling, two residual blocks, output projection, and a bilinear skip. The skip is deliberate: the
network learns the *correction* to the naive baseline rather than the image, so "beats bilinear" is a
statement about something learned, and a zero residual is exactly the baseline - which the gates below
detect instead of assuming.

The gates, all measured on held-out scenes rather than read off the training loss:
    beats the baseline   val L1 must be at least MIN_IMPROVEMENT below the bilinear upscale's
    is not the baseline  the output must differ from the bilinear upscale by more than BASELINE_FLOOR
    uses conditioning    zeroing depth, and zeroing motion, must each change the output. A model that
                         ignores an input the roadmap asked for has not been trained on it, and no
                         training loss would ever reveal that.
    reproducible         the same seed reproduces the same validation numbers

Usage:
    python tools/train_nrr.py --data models/training-data/v1 --out models/nrr_upscaler_trained.onnx
    python tools/train_nrr.py --self-test    # the gates must reject a model that is the baseline

Data path, all off by default so that every recorded number stays reproducible:
    --lazy          read the training split's files per batch instead of concatenating the whole split into
                    memory first. Same pairs, same order, same numbers; a dataset larger than RAM becomes
                    trainable. Validation is still loaded whole, because every val pair is forwarded anyway.
    --augment-flip  mirror each training sample on both axes at random, negating the motion and jitter
                    component that points along the mirrored axis so the mirrored pair stays *equal* to a
                    pair the capture could have produced.
    --crop-sizes N,M crops for multi-scale training: one size drawn per sample, the target cropped to the
                    matching window. A model trained at one frame size has seen one tier of it.

Requires: pip install torch, numpy, onnx. onnxruntime is optional and used only to confirm that the
exported graph agrees with PyTorch.

GPU: `--device auto` (the default) uses the GPU whenever torch can provide one, `--device cuda` refuses
to run on the CPU rather than pretend, and because a CPU-only torch wheel is the usual cause of a
"GPU training" session that never touches the GPU, the run records the device, the driver's own
utilization samples (nvidia-smi, sampled while training) and torch's peak allocation in its report. The
CPU-only wheel used for the first runs lives in the system Python; the CUDA wheel used here is in a
separate environment (G:\venvs\nrr-train, torch 2.3.1+cu121) so the two can be compared without
reinstalling anything:

    G:\venvs\nrr-train\Scripts\python.exe tools/train_nrr.py --data models/training-data/v1 \\
        --out models/nrr_upscaler_trained.onnx --epochs 45 --channels 48 --device auto
"""

import argparse
import hashlib
import json
import math
import os
import subprocess
import sys
import tempfile
import threading
import time

import numpy as np
import torch
import torch.nn as nn

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import quality_metrics  # noqa: E402  (path set above; PSNR/SSIM mirror runtime/nrr_quality.cpp)

# The names the C++ runtime reads out of the graph (runtime/onnx_runtime.cpp reads the session's own
# input and output names, and these are the ones models/architecture.md specifies).
INPUT_NAMES = ("color", "depth", "motion")
OUTPUT_NAME = "output"

# Measured thresholds, not preferences: each one is a floor below which the claim would be cosmetic.
MIN_IMPROVEMENT = 0.05      # at least 5% below the bilinear baseline on held-out scenes
BASELINE_FLOOR = 1e-3       # output must differ from the bilinear baseline by more than this
CONDITIONING_FLOOR = 1e-4   # zeroing an input must change the output by more than this
# The training loss must fall by at least this fraction from the first epoch to the last. Five of eight
# stage-4 runs sat at exactly the untrained-model loss and would otherwise have been reported as results;
# a run that does not learn is a fact about the run, and it belongs in the gate set rather than in prose.
MIN_TRAIN_PROGRESS = 0.10


def resolve_device(requested, log):
    """Chooses the device and refuses to pretend. Asking for cuda where torch cannot provide it is an
    error, not a quiet CPU run: a silent fallback is how a GPU result gets reported that never touched a
    GPU, which is the failure the C++ provider tests already forbid on the runtime side."""
    available = torch.cuda.is_available()
    if requested == "cuda" and not available:
        raise SystemExit(
            "--device cuda was requested but torch reports no usable CUDA device (torch %s, built with "
            "CUDA: %s, device_count: %d). Install a CUDA wheel, for example torch==2.3.1+cu121 from "
            "https://download.pytorch.org/whl/cu121, and re-run. Refusing to fall back to CPU silently."
            % (torch.__version__, torch.version.cuda, torch.cuda.device_count()))
    if not available:
        log("  device: cpu (torch %s has no CUDA support; cuda build is %s)"
            % (torch.__version__, torch.version.cuda))
        return torch.device("cpu"), {"used": "cpu", "requested": requested, "cuda_available": False,
                                     "torch": torch.__version__, "cuda_build": torch.version.cuda}
    device = torch.device("cuda" if requested == "auto" else requested)
    props = torch.cuda.get_device_properties(0)
    facts = {"used": device.type, "requested": requested, "cuda_available": True,
             "torch": torch.__version__, "cuda_build": torch.version.cuda,
             "device_name": torch.cuda.get_device_name(0),
             "capability": "sm_%d%d" % torch.cuda.get_device_capability(0),
             "total_memory_mb": round(props.total_memory / (1 << 20))}
    log("  device: %s (%s, %s, %d MB, torch %s built for CUDA %s)"
        % (device.type, facts["device_name"], facts["capability"], facts["total_memory_mb"],
           torch.__version__, torch.version.cuda))
    return device, facts


class GpuSampler(threading.Thread):
    """Samples the driver while training runs. A launched CUDA kernel is not the same thing as a used
    GPU: this asks nvidia-smi what the device was actually doing, so "the GPU was used" is a measurement
    rather than an inference from the device's presence."""

    def __init__(self, interval=0.4):
        super().__init__(daemon=True)
        self.interval = interval
        # Not named _stop: threading.Thread has an internal _stop() method, and an attribute of that name
        # shadows it, so Thread.join() fails with "TypeError: 'Event' object is not callable".
        self._halt = threading.Event()
        self.samples = []

    def run(self):
        while not self._halt.is_set():
            try:
                lines = subprocess.run(
                    ["nvidia-smi", "--query-gpu=utilization.gpu,memory.used",
                     "--format=csv,noheader,nounits"],
                    capture_output=True, text=True, timeout=5).stdout.strip().splitlines()
                for line in lines:
                    parts = [part.strip() for part in line.split(",")]
                    if len(parts) == 2:
                        self.samples.append((float(parts[0]), float(parts[1])))
            except Exception:
                pass  # a sampling gap is not a training failure
            self._halt.wait(self.interval)

    def stop(self):
        self._halt.set()
        self.join(timeout=5)

    def summary(self):
        if not self.samples:
            return {"samples": 0,
                    "note": "nvidia-smi produced no samples, so utilization was not measured"}
        usage = [sample[0] for sample in self.samples]
        memory = [sample[1] for sample in self.samples]
        return {"samples": len(self.samples),
                "utilization_percent": {"mean": round(sum(usage) / len(usage), 1), "max": max(usage)},
                "memory_used_mb": {"mean": round(sum(memory) / len(memory)), "max": max(memory)}}


def pair_from_npz(pair):
    """One pair file as float32 tensors in NCHW order.

    Both loaders below call this, so the eager and the lazy path cannot disagree about a key's name, order or
    dtype. `--lazy` is a statement about *when* a pair is read, never about what it contains - if the two
    disagreed, switching a dataset between them would silently change which inputs a run can use."""
    item = {
        "color": torch.from_numpy(pair["input"].transpose(2, 0, 1)[None].copy()),
        "depth": torch.from_numpy(pair["depth"][None, None].copy()),
        "motion": torch.from_numpy(pair["motion"].transpose(2, 0, 1)[None].copy()),
        "target": torch.from_numpy(pair["target"].transpose(2, 0, 1)[None].copy())}
    # history and validity exist in captures (tools/pack_godot_pairs.py) but not in procedural
    # pairs. Their absence is not an error - a run that does not ask for them must still work - and
    # their presence is what makes the history comparison possible at all.
    if "history" in pair:
        item["history"] = torch.from_numpy(pair["history"].transpose(2, 0, 1)[None].copy())
    # Jitter is the sub-pixel offset this frame's low-resolution sample was taken at, in
    # low-resolution pixels, +x right +y down. It is one 2-vector per frame but is broadcast to a
    # plane here, because a convolution cannot consume a 2-vector and the whole point of telling the
    # model where the frame was sampled is so it can correct for it. Without this a temporal model
    # trained on jittered captures cannot know its own sampling grid, which is the information that
    # separates a jitter-aware temporal resolve from an unaware one.
    if "jitter" in pair:
        height, width = pair["input"].shape[0], pair["input"].shape[1]
        item["jitter"] = torch.from_numpy(pair["jitter"].astype(np.float32)) \
            .view(1, 2, 1, 1).expand(1, 2, height, width).clone()
    # Validity is the capture's own mask on the history it carries: 1 where this pixel's history is
    # trustworthy, 0 where the reprojection left the frame, where the previous frame held something nearer, or
    # where there is no geometry at all (sky). It is loaded as an *input* rather than as metadata because a
    # model that is not told which of its history samples to trust has to infer it from pixels and geometry,
    # and that inference is exactly what the first temporal arms measured badly.
    if "validity" in pair:
        item["validity"] = torch.from_numpy(pair["validity"][None, None].copy())
    return item



class Split:
    """One split's pairs, held either as concatenated tensors (eager) or as the files they came from (lazy).

    Both answer the same questions - `keys`, `count`, `batch(index)` - so the training loop does not know or
    care which it was given, and a lazy run and an eager run of the same seed produce the same tensors in the
    same order. `zero()` and `to_()` are the two places the driver used to reach into the tensors directly.

    Eager is the default because it is faster: each split is moved to the device once. Lazy exists because
    "the dataset fits in memory" is a limit a capture factory crosses - a few thousand 128x128 pairs fit, a
    few hundred thousand do not - and the fix for that has to be a loader change, not a smaller dataset.
    """

    def __init__(self, keys, device=None, tensors=None, paths=None):
        self.keys = list(keys)
        self.device = device
        self.tensors = tensors                  # eager: {key: (N, C, H, W) tensor}, nothing left to read
        self.paths = paths                      # lazy: one pair file per position, read on demand
        self.count = tensors[self.keys[0]].shape[0] if tensors is not None else len(paths)
        self.zeroed = set()

    def __contains__(self, key):
        return key in self.keys

    def zero(self, key):
        """Ablation, for the whole split. Eager replaces the tensor with zeros; lazy remembers not to hand it
        over. The two produce the same zeros, which is the only thing an ablation is allowed to differ by."""
        if key not in self.keys:
            return
        if self.tensors is not None:
            self.tensors[key] = torch.zeros_like(self.tensors[key])
        self.zeroed.add(key)

    def to_(self, device):
        """Places the split on `device`: eager moves its tensors once, lazy materialises straight onto it."""
        self.device = device
        if self.tensors is not None:
            self.tensors = {key: value.to(device) for key, value in self.tensors.items()}

    def _positions(self, index):
        """Turns whatever the caller indexed with into pair positions, because a lazy split indexes files
        rather than tensors and cannot slice a list of names."""
        if isinstance(index, slice):
            return list(range(*index.indices(self.count)))
        if isinstance(index, torch.Tensor):
            return [int(value) for value in index.flatten()]
        if isinstance(index, (list, tuple, range, np.ndarray)):
            return [int(value) for value in index]
        return [int(index)]

    def batch(self, index):
        """The pairs at `index` as one dict of tensors, on this split's device.

        Eager slices what is already in memory; lazy reads those pairs from disk now, which is the whole
        difference between the two. Nothing else about a batch depends on which path produced it.
        """
        if self.tensors is not None:
            return {key: self.tensors[key][index] for key in self.keys}
        pieces = []
        for position in self._positions(index):
            with np.load(self.paths[position]) as pair:
                pieces.append(pair_from_npz(pair))
        batch = {}
        for key in self.keys:
            value = torch.cat([piece[key] for piece in pieces], dim=0)
            if key in self.zeroed:
                value = torch.zeros_like(value)
            batch[key] = value.to(self.device)
        return batch

    def materialise(self):
        """The whole split as one dict of tensors. Used by the driver for validation, whose every pair has to
        be forwarded to produce the held-out number."""
        if self.tensors is not None:
            return self.tensors
        return self.batch(slice(0, self.count))

    def frame_shape(self):
        """(height, width) of the low-resolution input grid, from the first pair and without materialising the
        split, so the augmentation arguments can be checked against it before training starts."""
        if self.tensors is not None:
            return tuple(self.tensors["color"].shape[-2:])
        with np.load(self.paths[0]) as pair:
            return (int(pair["input"].shape[0]), int(pair["input"].shape[1]))


def load_dataset(data_dir, lazy=False):
    """Loads the manifest and the pairs it names.

    Returns (manifest, dataset) where dataset["train"] and dataset["val"] are Split objects, sizes[split] is
    that split's pair count, and has_history / has_jitter say whether the pairs carry a previous frame and a
    sampling offset.

    `lazy` reads the *training* split's files per batch instead of concatenating the whole split into memory
    first. Which optional inputs a dataset has is decided from the files either way, so a mixture of captured
    and procedural pairs is refused before any of them is read, not discovered halfway through training."""
    manifest_path = os.path.join(data_dir, "manifest.json")
    if not os.path.exists(manifest_path):
        raise SystemExit("%s has no manifest.json - run tools/gen_training_pairs.py first" % data_dir)
    with open(manifest_path, encoding="utf-8") as handle:
        manifest = json.load(handle)

    entries = {"train": [], "val": []}
    pairs = []
    for entry in manifest["pairs"]:
        path = os.path.join(data_dir, entry["file"])
        # np.load reads a zip archive's directory to answer this, not the arrays, so asking which optional
        # inputs a pair carries costs almost nothing and does not depend on the pair being materialised.
        with np.load(path) as file:
            present = set(file.files)
        pairs.append((entry, path, present))
        entries[entry["split"]].append(pairs[-1])

    for split in ("train", "val"):
        if not entries[split]:
            raise SystemExit(
                "the dataset has no %s pairs (train=%d, val=%d) - regenerate with a smaller "
                "--val-every, or more pairs" % (split, len(entries["train"]), len(entries["val"])))

    def uniform(key):
        """Whether every pair in the dataset carries `key`. Its absence is not an error - a run that does not
        ask for it must still work - but a mixture is refused rather than half-supported, because the two
        kinds concatenate different channel counts together."""
        flags = {key in present for _, _, present in pairs}
        if len(flags) > 1:
            raise SystemExit("the dataset mixes pairs with and without %s; use one capture per dataset" % key)
        return flags == {True}

    keys = ["color", "depth", "motion", "target"]
    # Whether history is there is decided before anything is loaded, and the same way for both loaders: it is
    # what makes the history comparison possible at all.
    has_history = uniform("history")
    if has_history:
        keys.append("history")
    has_jitter = uniform("jitter")
    if has_jitter:
        keys.append("jitter")
    # Validity follows the same all-or-nothing rule: it is the mask that says which of those history samples
    # can be trusted, and a dataset that had it for some pairs and not others would mean something different
    # per pair.
    has_validity = uniform("validity")
    if has_validity:
        keys.append("validity")

    dataset = {"has_history": has_history, "has_jitter": has_jitter, "has_validity": has_validity,
               "sizes": {split: len(items) for split, items in entries.items()}}
    for split, items in entries.items():
        if lazy and split == "train":
            # Only the training split takes this path: validation is forwarded in full to produce the
            # held-out number, so laziness there would save a third of a split that is already a small
            # fraction of the data, and would complicate the metric path for nothing.
            dataset[split] = Split(keys, paths=[path for _, path, _ in items])
        else:
            loaded = []
            for _, path, _ in items:
                with np.load(path) as pair:
                    loaded.append(pair_from_npz(pair))
            dataset[split] = Split(keys, tensors={key: torch.cat([item[key] for item in loaded], dim=0)
                                                  for key in keys})
    return manifest, dataset


def augment_scale(height, width, crop_sizes, generator):
    """The crop size this batch is trained at, drawn once per batch from `crop_sizes`.

    Per batch and not per sample, because a batch is one tensor: samples cropped to different sizes cannot be
    stacked into the tensor a convolution consumes. This was measured, not reasoned about - the first run with
    two crop sizes died on torch.cat with "expected size 96 but got size 112" - and it is the standard shape of
    the lever anyway: the tier varies between batches, while each sample in the batch still gets its own
    window and its own mirrors below. So multi-scale training is many tiers over an epoch, not one tier per
    sample within a step.
    """
    if not crop_sizes:
        return height, width
    side = int(crop_sizes[int(torch.randint(len(crop_sizes), (1,), generator=generator))])
    crop_h = max(min(side, height), 1)
    # Width follows the frame's aspect ratio, so --crop-sizes names a height and a non-square capture is
    # cropped rather than squashed.
    crop_w = max(min(int(round(side * width / float(height))), width), 1)
    return crop_h, crop_w


def augment_draw(height, width, crop_h, crop_w, flip, generator):
    """One sample's mirror and crop position, drawn from `generator`.

    Kept apart from the application below so a test can hand-build a decision - "mirror horizontally, crop
    here" - and check what the application does with it, rather than hoping a random draw happened to produce
    the case under test."""
    if flip:
        # The two axes are drawn independently: a horizontal and a vertical mirror are different transforms
        # with different consequences for the direction fields below (one negates x, the other y), and a
        # single draw for both would leave them unexercised apart.
        flip_h = bool(torch.randint(2, (1,), generator=generator))
        flip_v = bool(torch.randint(2, (1,), generator=generator))
    else:
        flip_h = flip_v = False
    offset_y = int(torch.randint(height - crop_h + 1, (1,), generator=generator)) if crop_h < height else 0
    offset_x = int(torch.randint(width - crop_w + 1, (1,), generator=generator)) if crop_w < width else 0
    return {"flip_h": flip_h, "flip_v": flip_v, "crop_h": crop_h, "crop_w": crop_w,
            "offset_y": offset_y, "offset_x": offset_x}


def _mirror(piece, plan):
    """The mirror half of a plan, applied to a tensor shaped (N, C, H, W)."""
    if plan["flip_h"]:
        piece = torch.flip(piece, dims=(-1,))
    if plan["flip_v"]:
        piece = torch.flip(piece, dims=(-2,))
    return piece


def augment_sample(pair, plan, scale_y, scale_x):
    """Applies one plan to one pair, whose tensors are each shaped (1, C, H, W).

    Why a mirrored pair is still a real pair: every transform that makes one is equivariant under a mirror.
    The images carry over unchanged - history is on the same grid as the input and was warped into that grid
    before it was saved, so mirroring the input and the history together mirrors the pair - and a crop is
    aligned by construction, since the target is the input's grid at `scale`. What does *not* carry over
    untouched is the sign of the direction fields: motion and jitter point along +x/+y (frame_contract.md
    4.3), so a horizontal mirror negates their x component and a vertical mirror negates their y. Training on
    pairs whose motion points the wrong way is worse than not augmenting at all.
    """
    out = {}
    for key, value in pair.items():
        if key in ("motion", "jitter"):
            continue                      # signed direction fields, cropped and mirrored below
        if key == "target":
            # The target is the higher-resolution grid, so it is cropped at the same place *in image terms*:
            # the low-resolution window multiplied by the scale. Cropping it at the same pixel offset instead
            # would take it from a different part of the image, and the model would be trained to reproduce
            # an offset pair.
            piece = value[..., plan["offset_y"] * scale_y:(plan["offset_y"] + plan["crop_h"]) * scale_y,
                          plan["offset_x"] * scale_x:(plan["offset_x"] + plan["crop_w"]) * scale_x]
        else:
            piece = value[..., plan["offset_y"]:plan["offset_y"] + plan["crop_h"],
                          plan["offset_x"]:plan["offset_x"] + plan["crop_w"]]
        out[key] = _mirror(piece, plan)
    for key in ("motion", "jitter"):
        if key not in pair:
            continue
        # Both are on the low-resolution grid and are cropped by the same window as everything else. For
        # jitter that changes no *value* - it is one offset broadcast over the frame - but it is not optional:
        # the model concatenates the jitter plane with the input's own features, so a full-sized jitter plane
        # against a cropped input is a shape mismatch, which is exactly how this was found ("96 must match
        # 128"). A broadcast input is still an input.
        piece = pair[key][..., plan["offset_y"]:plan["offset_y"] + plan["crop_h"],
                          plan["offset_x"]:plan["offset_x"] + plan["crop_w"]]
        piece = _mirror(piece, plan)
        # Channel 0 is x and channel 1 is y, both pointing +right/+down: a mirror reverses the component
        # along the axis it mirrors and leaves the other one alone.
        if plan["flip_h"]:
            piece = torch.cat([-piece[:, 0:1], piece[:, 1:2]], dim=1)
        if plan["flip_v"]:
            piece = torch.cat([piece[:, 0:1], -piece[:, 1:2]], dim=1)
        out[key] = piece
    return out


def augment_batch(batch, crop_sizes, flip, generator):
    """Augments a training batch: one crop tier per batch, one window and mirror per sample.

    The crop size is drawn once for the whole batch because samples cropped to different sizes cannot be
    stacked into one tensor (see augment_scale), but the offset and the mirror are drawn per sample, because a
    batch is a stack of unrelated frames and a single mirror for all four is a much smaller change than it
    looks. `generator` is the training loop's own generator, which is why an augmented run is still pinned by
    --deterministic.
    """
    color = batch["color"]
    height, width = int(color.shape[-2]), int(color.shape[-1])
    target = batch.get("target")
    if target is None:
        raise SystemExit("augmentation needs the target: there is nothing to align a crop against")
    scale_y = target.shape[-2] // height
    scale_x = target.shape[-1] // width
    if target.shape[-2] != height * scale_y or target.shape[-1] != width * scale_x:
        raise SystemExit(
            "the target is %dx%d against a %dx%d input, which is not an integer scale, so a crop of the pair "
            "cannot be aligned to the same part of the image"
            % (target.shape[-2], target.shape[-1], height, width))
    crop_h, crop_w = augment_scale(height, width, crop_sizes, generator)
    pieces = []
    for index in range(color.shape[0]):
        plan = augment_draw(height, width, crop_h, crop_w, flip, generator)
        pieces.append(augment_sample({key: value[index:index + 1] for key, value in batch.items()},
                                     plan, scale_y, scale_x))
    return {key: torch.cat([piece[key] for piece in pieces], dim=0) for key in batch}


def take(batch, index, keys):
    """Slices a split down to one batch. `keys` comes from the dataset so a pair with history is sliced
    with it and one without is not."""
    return {key: batch[key][index] for key in keys}


def check_gates(numbers, zeroed=None, inputs=("color", "depth", "motion")):
    """Returns the reasons a model fails to qualify, as a list, so a run reports every failure rather
    than only the first. Called before anything is exported, and used by the self-test.

    `zeroed` names an input that this run deliberately ablated: a model cannot be blamed for ignoring an
    input it was never given, so that one gate is skipped. `inputs` is what the model actually consumes,
    because a colour-only model has no history weights to ignore and must not be failed for not using
    something it does not have."""
    failures = []
    # Checked first, because every other number below is meaningless if the run never learned: a stalled
    # model reports the untrained-model loss, and its held-out figure would otherwise be compared as if it
    # were a result of a different input set.
    if numbers.get("train_progress", 1.0) < MIN_TRAIN_PROGRESS:
        failures.append(
            "training made no progress: residual L1 went from %.5f to %.5f, a fall of %.1f%% (needs >= "
            "%.0f%%) - this run is degenerate and its numbers are not a comparison result"
            % (numbers.get("train_first_loss", 0.0), numbers.get("train_last_loss", 0.0),
               numbers.get("train_progress", 0.0) * 100.0, MIN_TRAIN_PROGRESS * 100.0))
    if numbers["val_l1"] > numbers["val_baseline_l1"] * (1.0 - MIN_IMPROVEMENT):
        failures.append(
            "does not beat the baseline: val L1 %.5f against the bilinear baseline's %.5f, which is "
            "not at least %.0f%% lower" % (numbers["val_l1"], numbers["val_baseline_l1"],
                                           MIN_IMPROVEMENT * 100.0))
    if numbers["drift"] <= BASELINE_FLOOR:
        failures.append(
            "is the baseline: its output differs from the bilinear upscale by only %.6f (needs > "
            "%.4f), so nothing was learned" % (numbers["drift"], BASELINE_FLOOR))
    for field in ("depth_ablation", "motion_ablation", "history_ablation", "jitter_ablation",
                  "validity_ablation"):
        name = field.split("_")[0]
        if name not in inputs or (zeroed and field.startswith(zeroed)):
            continue
        if numbers[field] <= CONDITIONING_FLOOR:
            failures.append(
                "ignores %s: zeroing it changes the output by only %.6f (needs > %.4f)"
                % (name, numbers[field], CONDITIONING_FLOOR))
    return failures


def export_onnx(model, out_path, size, inputs, opset=17):
    """Exports with the input names models/architecture.md specifies and dynamic H/W, so the runtime is not
    tied to the size this model happened to be trained at. The tensor list follows the selected inputs,
    because a colour-only model must not declare three inputs the runtime would have to invent.

    The example tensors and the trace both stay on the CPU. Building them on the model's own device was
    the previous behaviour, and it was invisible while training ran on the CPU and became an immediate
    failure the moment training moved to the GPU: "Input type (torch.FloatTensor) and weight type
    (torch.cuda.FloatTensor) should be the same".

    The order the tensors are passed in is the model's own forward signature - (color, depth, motion, history) - and
    not the order this model happens to consume. Passing them positionally in `inputs` order bound them to
    the signature's parameter slots, so a `--inputs=color,motion,history` model fed its 3-channel history
    tensor into the 2-channel motion convolution and the export died with "expected input[1, 3, 128, 128] to
    have 2 channels". Every model exported before this one was colour-only, so the bug sat behind a
    single-input signature that cannot express it. They are now placed by name and a None is passed for each
    input the model does not consume, which is what the signature's defaults already expect.

    The weights are moved to the CPU for the trace and back afterwards. Tracing on the GPU worked until
    `--deterministic` was added: torch's deterministic path rewrites `F.interpolate` (the 2x bilinear skip)
    into a decomposition that builds its index tensors on the CPU, which then cannot be clamped against CUDA
    values - "found at least two devices, cuda:0 and cpu" - and the export died for a model whose training
    had completed and passed every gate. ONNX tracing needs no accelerator, and the runtime that consumes
    this graph runs it on the CPU, so the CPU is also the honest place to trace it."""
    widths = {"color": 3, "depth": 1, "motion": 2, "history": 3, "jitter": 2, "validity": 1}
    signature = ("color", "depth", "motion", "history", "jitter", "validity")
    os.makedirs(os.path.dirname(os.path.abspath(out_path)), exist_ok=True)
    example = tuple(torch.zeros(1, widths[name], size, size) if name in inputs else None
                    for name in signature)
    ordered = [name for name in signature if name in inputs]
    # Dynamic axes only for inputs the graph actually declares: naming an axis for an input the model does not
    # consume makes torch warn that the key "is not a valid input/output name", which trains the reader to
    # ignore warnings from this call.
    dynamic = {name: {2: "H", 3: "W"} for name in ordered}
    dynamic[OUTPUT_NAME] = {2: "H2", 3: "W2"}
    training_device = next(model.parameters()).device
    model.to("cpu")
    try:
        torch.onnx.export(model, example, out_path, opset_version=opset, input_names=ordered,
                          output_names=[OUTPUT_NAME], dynamic_axes=dynamic)
    finally:
        # The caller keeps using this model (the export is verified against it on the training device), so it
        # goes back where it came from even if the trace failed.
        model.to(training_device)
    return out_path


def _sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(1 << 20), b""):
            digest.update(chunk)
    return digest.hexdigest()


def run(args, log):
    manifest_path = os.path.join(args.data, "manifest.json")
    manifest, dataset = load_dataset(args.data, lazy=args.lazy)
    summary = manifest.get("summary", {})
    log("  dataset: %d train / %d val pairs; manifest margin min %.4f, noise %.4f, detail ratio max %.3f"
        % (dataset["sizes"]["train"], dataset["sizes"]["val"],
           summary.get("margin", {}).get("min", float("nan")),
           summary.get("noise", {}).get("max", float("nan")),
           summary.get("detail_ratio", {}).get("max", float("nan"))))
    log("  loading: %s" % ("lazy, the training split is read per batch"
                           if args.lazy else "eager, every split is concatenated into memory once"))

    # Augmentation is off unless asked for, and deliberately so: every number this repository has recorded
    # was produced without it, so turning a transform on by default would silently invalidate all of them.
    crop_sizes = tuple(sorted({int(value) for value in args.crop_sizes.split(",") if value.strip()}))
    frame_height, _ = dataset["train"].frame_shape()
    for size in crop_sizes:
        if size < 8:
            raise SystemExit("--crop-sizes %d is smaller than 8 pixels, which is not a crop of a frame but a "
                             "cropout of it" % size)
        if size > frame_height:
            raise SystemExit("--crop-sizes %d is larger than the dataset's %d-pixel frames, so it would do "
                             "nothing at all" % (size, frame_height))
    augment = None
    if crop_sizes or args.augment_flip:
        augment = {"crop_sizes": crop_sizes, "flip": bool(args.augment_flip)}
        log("  augmentation: %s, crops %s (every mirror negates the matching motion and jitter component)"
            % ("mirror each sample on both axes at random" if args.augment_flip else "no mirror",
               "/".join(str(size) for size in crop_sizes) if crop_sizes else "none"))

    requested = ["color"] + [name.strip() for name in args.inputs.split(",") if name.strip()]
    available = {"color"} | {key for key in ("depth", "motion", "history", "jitter", "validity")
                             if key in dataset["train"]}
    missing = [name for name in requested if name not in available]
    if missing:
        raise SystemExit(
            "this dataset has no %s (it has: %s). A model cannot be given an input the data does not "
            "contain, and inventing zeros for it would measure nothing." % (", ".join(missing),
                                                                           ", ".join(sorted(available))))
    requested = [name for name in ("color", "depth", "motion", "history", "jitter", "validity")
                 if name in requested]
    log("  inputs: %s%s" % (",".join(requested),
                            " (history available)" if dataset["has_history"] else ""))

    zeroed = None if args.zero_input == "none" else args.zero_input
    if zeroed:
        # Ablation training: the input is removed from training *and* validation, so the comparison is
        # like for like. Measuring what an input is worth is the only way to tell a model that fails to
        # use it apart from data on which it cannot be used.
        for split in ("train", "val"):
            dataset[split].zero(zeroed)
        log("  ablation: '%s' is zeroed for training and validation" % zeroed)

    device, device_facts = resolve_device(args.device, log)
    # Each split is placed on the device once rather than per batch: an eager split is small enough to live
    # there whole and a transfer per step would dominate a model this size, while a lazy split materialises
    # each batch onto the device as it reads it.
    for split in ("train", "val"):
        dataset[split].to_(device)
    if device.type == "cuda":
        # cuDNN autotuning picks a convolution algorithm by timing candidates, so two runs of the *same* seed
        # can take different arithmetic paths and drift apart - measured here, not assumed: the same
        # config and seed reached 8.4% and 0.0% training progress on two runs, which makes "the seed" a
        # claim the report cannot support. --deterministic turns autotuning off and asks for deterministic
        # kernels, so a seed pins a result. It costs some speed, which is why it is opt-in rather than
        # forced: a run whose number cannot be reproduced is not a measurement, but a run being 2x slower is
        # a known and stated cost.
        torch.backends.cudnn.benchmark = not args.deterministic
        torch.backends.cudnn.deterministic = bool(args.deterministic)
        if args.deterministic:
            torch.use_deterministic_algorithms(True, warn_only=True)
            log("  deterministic: cuDNN autotuning off, deterministic kernels requested (--deterministic)")

    sampler = GpuSampler() if device.type == "cuda" else None
    if sampler is not None:
        sampler.start()
        torch.cuda.synchronize()   # so the wall clock times the GPU's work, not the kernel launches
    started = time.time()
    model, parameters, first_loss, last_loss, first_plain, last_plain = train(
        dataset, requested, args.epochs, args.batch_size, args.channels, args.depth_channels,
        args.motion_channels, args.history_channels, args.learning_rate, args.warmup_epochs,
        args.seed, device, log,
                                                     loss_name=args.loss,
                                                     ssim_weight=args.ssim_weight,
                                                     lr_schedule=args.lr_schedule,
                                                     detail_weight=args.detail_weight,
                                                      jitter_channels=args.jitter_channels,
                                                      validity_channels=args.validity_channels,
                                                      augment=augment)
    if device.type == "cuda":
        torch.cuda.synchronize()
    seconds = time.time() - started
    gpu_usage = None
    if sampler is not None:
        sampler.stop()
        gpu_usage = sampler.summary()
        log("  gpu: %s over %d samples; peak allocated by torch %.1f MB"
            % (gpu_usage.get("utilization_percent", "not measured"), gpu_usage["samples"],
               torch.cuda.max_memory_allocated() / (1 << 20)))
    log("  training: %.1f s total, %.1f ms/epoch" % (seconds, seconds / max(args.epochs, 1) * 1000.0))

    val = dataset["val"].materialise()
    full = measure(model, val, chunk=args.measure_batch)
    keys = list(val.keys())

    def ablation(name):
        """How much the output changes when `name` is zeroed. Only inputs the model actually consumes are
        measured, so a colour-only model reports zeros for the others rather than numbers from weights it
        does not have."""
        if name not in model.inputs:
            return 0.0
        return float((full["output"] - measure(model, val, zero=name, chunk=args.measure_batch)["output"]).abs().mean())

    depth_ablation = ablation("depth")
    motion_ablation = ablation("motion")
    history_ablation = ablation("history")
    jitter_ablation = ablation("jitter")
    validity_ablation = ablation("validity")
    # The metrics a caller checks, not only L1. Computed for the model and for the bilinear baseline on the
    # same held-out frames, so the comparison is like for like and the baseline's score is visible too.
    model_quality = quality_metrics.evaluate(full["output"], val["target"])
    baseline_quality = quality_metrics.evaluate(full["baseline"], val["target"])
    numbers = {"val_l1": full["l1"], "val_baseline_l1": full["baseline_l1"], "drift": full["drift"],
               "depth_ablation": depth_ablation, "motion_ablation": motion_ablation,
               "history_ablation": history_ablation, "jitter_ablation": jitter_ablation,
               "validity_ablation": validity_ablation,
               "ssim": model_quality["ssim"], "psnr_db": model_quality["psnr_db"],
               "ms_ssim": model_quality["ms_ssim"],
               "baseline_ssim": baseline_quality["ssim"],
               "baseline_psnr_db": baseline_quality["psnr_db"],
               "baseline_ms_ssim": baseline_quality["ms_ssim"],
               "train_first_loss": first_loss, "train_last_loss": last_loss,
               # The objective, kept for transparency about what was actually optimised - it is not the
               # gate, because its scale moves with --loss and --detail-weight (0.0148 for a plain L1 run,
               # 0.035 for a detail-weighted one, so the same percentage means different things).
               "train_first_l1": first_plain, "train_last_l1": last_plain,
               "train_progress": (first_plain - last_plain) / max(first_plain, 1e-9),
               "objective_progress": (first_loss - last_loss) / max(first_loss, 1e-9),
               "improvement": 1.0 - full["l1"] / max(full["baseline_l1"], 1e-9)}
    log("  val L1 %.5f against the bilinear baseline's %.5f -> %.2f%% better; drift from baseline %.5f"
        % (numbers["val_l1"], numbers["val_baseline_l1"], numbers["improvement"] * 100.0,
           numbers["drift"]))
    log("  ablations (how much the output moves when the input is zeroed): depth %.5f, motion %.5f, "
        "history %.5f, jitter %.5f, validity %.5f"
        % (depth_ablation, motion_ablation, history_ablation, jitter_ablation, validity_ablation))
    log("  quality: ssim %.4f psnr %.2f dB against the bilinear baseline's ssim %.4f psnr %.2f dB"
        % (numbers["ssim"], numbers["psnr_db"], numbers["baseline_ssim"],
           numbers["baseline_psnr_db"]))
    # MS-SSIM beside SSIM, because the two disagree exactly where a still-image metric is weakest: SSIM at the
    # pixel scale says nothing about whether the reconstruction is right at the scale the eye reads, and the
    # multi-scale term is what a commercial upscaler's structure claims are usually quoted in.
    scales = quality_metrics.ms_ssim_scales(val["target"].shape[-2:]
                                           if val["target"].ndim >= 3 else (0, 0))
    log("  ms-ssim: %.4f against the bilinear baseline's %.4f (%d of 5 scales at this resolution)"
        % (numbers["ms_ssim"], numbers["baseline_ms_ssim"], scales))
    log("  training progress: unweighted residual L1 %.5f -> %.5f (%.1f%% lower)"
        % (first_plain, last_plain, numbers["train_progress"] * 100.0))
    if abs(numbers["objective_progress"] - numbers["train_progress"]) > 0.02:
        # Only worth a line when the objective and the gated quantity actually disagree, which is the
        # weighted-loss case; for a plain L1 run they are the same number.
        log("    (the %s objective itself moved %.1f%%; the gate reads the unweighted number so it means"
            " the same thing for every configuration)"
            % (args.loss, numbers["objective_progress"] * 100.0))

    failures = check_gates(numbers, zeroed, model.inputs)
    report = {"model": "nrr_upscaler_trained", "parameters": parameters, "inputs": list(model.inputs),
              "channels": args.channels,
              "depth_channels": args.depth_channels, "motion_channels": args.motion_channels,
              "epochs": args.epochs, "batch_size": args.batch_size,
              "learning_rate": args.learning_rate, "seed": args.seed,
              "loss": args.loss, "ssim_weight": args.ssim_weight, "lr_schedule": args.lr_schedule,
              "detail_weight": args.detail_weight,
              "deterministic": bool(args.deterministic),
              "zeroed_input": zeroed,
              # Recorded because a metric is only comparable to one produced the same way: a run with
              # augmentation and a run without are two configurations, so the report has to say which it was.
              "loading": "lazy" if args.lazy else "eager",
              "augmentation": ({"flip": augment["flip"], "crop_sizes": list(augment["crop_sizes"])}
                               if augment else None),
              "device": device_facts,
              "gpu": gpu_usage or {"samples": 0,
                                   "note": "not a CUDA run, so utilization was not sampled"},
              "gpu_torch_peak_memory_mb": (round(torch.cuda.max_memory_allocated() / (1 << 20))
                                           if device.type == "cuda" else None),
              "train_seconds": round(seconds, 2),
              "dataset": {"dir": args.data, "manifest_sha256": _sha256(manifest_path),
                          "generator": manifest.get("generator"), "seed": manifest.get("seed"),
                          "count": manifest.get("count"), "sizes": dataset["sizes"]},
              "measured": numbers,
              "gates": {"min_improvement": MIN_IMPROVEMENT, "baseline_floor": BASELINE_FLOOR,
                        "conditioning_floor": CONDITIONING_FLOOR, "failures": failures}}
    report_path = os.path.splitext(args.out)[0] + ".report.json"

    if failures:
        # A model that does not qualify is not exported at all, and the refusal is written down: an
        # exported file with a warning printed next to it gets used anyway.
        log("  REFUSING to export: %d gate(s) failed, so this model does not qualify" % len(failures))
        for failure in failures:
            log("    - %s" % failure)
        with open(report_path, "w", encoding="utf-8", newline="\n") as handle:
            json.dump(report, handle, indent=2)
            handle.write("\n")
        log("  report: %s (the refusal is recorded, not swallowed)" % report_path)
        return 1

    export_onnx(model, args.out, args.size, model.inputs)
    verification = verify_export(model, args.out, take(val, slice(0, 1), keys))
    report["export"] = {"path": args.out, "opset": 17, "sha256": _sha256(args.out),
                        "verify": verification}
    # Dynamic H/W is what makes the graph usable by the runtime at sizes it was not trained at, so it is
    # checked rather than assumed.
    try:
        import onnxruntime
        session = onnxruntime.InferenceSession(args.out, providers=["CPUExecutionProvider"])
        other = args.size + 32
        widths = {"color": 3, "depth": 1, "motion": 2, "history": 3, "jitter": 2, "validity": 1}
        produced = list(session.run([OUTPUT_NAME], {
            name: np.zeros((1, widths[name], other, other), np.float32)
            for name in model.inputs})[0].shape)
        expected = [1, 3, other * 2, other * 2]
        report["export"]["dynamic_size_check"] = {"input_size": other, "output_shape": produced,
                                                  "expected": expected}
        if produced != expected:
            log("  FAILED: the exported graph is not dynamic in H/W (got %s, expected %s)"
                % (produced, expected))
            return 1
    except ImportError:
        report["export"]["dynamic_size_check"] = {"checked": False}

    with open(report_path, "w", encoding="utf-8", newline="\n") as handle:
        json.dump(report, handle, indent=2)
        handle.write("\n")
    log("  exported: %s (%d parameters, %.1f s of training)" % (args.out, parameters, seconds))
    if verification.get("checked"):
        log("  onnxruntime %s agrees with PyTorch to %.2e; dynamic H/W verified"
            % (verification["onnxruntime"], verification["max_abs_difference"]))
    log("  report: %s" % report_path)
    return 0


def verify_export(model, out_path, batch):
    """Confirms the exported graph agrees with PyTorch, using onnxruntime when it is installed. An
    export nobody checked is a file, not a deliverable."""
    try:
        import onnxruntime
    except ImportError:
        return {"checked": False, "reason": "onnxruntime is not installed"}
    import onnx
    onnx.checker.check_model(onnx.load(out_path))
    session = onnxruntime.InferenceSession(out_path, providers=["CPUExecutionProvider"])
    signature = ("color", "depth", "motion", "history", "jitter", "validity")
    keys = [name for name in signature if name in model.inputs]
    # .cpu() because the batch lives on the model's device and numpy cannot read a CUDA tensor; onnxruntime
    # is happiest with plain host arrays.
    feeds = {name: batch[name].detach().cpu().numpy() for name in keys}
    # The reference run uses the model's own device for the same reason export_onnx does: torch refuses to
    # convolve a CPU tensor with a CUDA weight, and onnxruntime is happiest with plain CPU arrays.
    # The tensors are placed into the forward signature's own slots rather than splatted in `keys` order:
    # for a color+motion+history model that splat fed the 3-channel history into the 2-channel motion
    # convolution, so the check that exists to catch a bad export was itself the thing that crashed. A
    # verification step that cannot run verifies nothing.
    device = next(model.parameters()).device
    with torch.no_grad():
        reference = model(*[batch[name].to(device) if name in keys else None
                            for name in signature]).cpu().numpy()
    produced = session.run([OUTPUT_NAME], feeds)[0]
    return {"checked": True, "onnxruntime": onnxruntime.__version__,
            "max_abs_difference": float(np.max(np.abs(reference - produced)))}


def self_test():
    """Proves the gates are not decorative without needing a training run: the baseline itself must be
    rejected, and so must a model that improves the image while ignoring its conditioning."""
    cases = [
        ("the baseline itself", {"val_l1": 0.02, "val_baseline_l1": 0.02, "drift": 0.0,
                                 "depth_ablation": 0.0, "motion_ablation": 0.0,
                                 "history_ablation": 0.0, "train_progress": 0.5},
         ("color", "depth", "motion"), 4),
        ("better but conditioning-blind", {"val_l1": 0.015, "val_baseline_l1": 0.02, "drift": 0.002,
                                           "depth_ablation": 0.0, "motion_ablation": 0.0,
                                           "history_ablation": 0.0, "train_progress": 0.5},
         ("color", "depth", "motion"), 2),
        # This case only fails if the history gate is applied, which is why each case carries the input set
        # it is about: a model with no history weights cannot be failed for ignoring history, and a model
        # that has them must be.
        ("better but history-blind", {"val_l1": 0.015, "val_baseline_l1": 0.02, "drift": 0.002,
                                      "depth_ablation": 0.001, "motion_ablation": 0.001,
                                      "history_ablation": 0.0, "train_progress": 0.5},
         ("color", "depth", "motion", "history"), 1),
        ("better and conditioning-aware", {"val_l1": 0.015, "val_baseline_l1": 0.02, "drift": 0.002,
                                           "depth_ablation": 0.001, "motion_ablation": 0.001,
                                           "history_ablation": 0.001, "train_progress": 0.5},
         ("color", "depth", "motion", "history"), 0),
        # A run that learned nothing must be rejected even when it happens to look acceptable on the other
        # numbers, because a degenerate run is not a comparison result. This is the failure that hid in
        # five of the eight stage-4 runs.
        ("stalled run", {"val_l1": 0.01, "val_baseline_l1": 0.02, "drift": 0.002,
                         "depth_ablation": 0.001, "motion_ablation": 0.001, "history_ablation": 0.001,
                         "train_progress": 0.0, "train_first_loss": 0.0148, "train_last_loss": 0.0148},
         ("color", "depth", "motion", "history"), 1),
    ]
    # Jitter. The model must actually use the sampling offset it is given, and a jitter-blind model must be
    # caught - otherwise "temporal with antialiasing" would be a claim no test could falsify.
    cases.append(("better but jitter-blind",
                  {"val_l1": 0.015, "val_baseline_l1": 0.02, "drift": 0.002, "depth_ablation": 0.001,
                   "motion_ablation": 0.001, "history_ablation": 0.001, "jitter_ablation": 0.0,
                   "train_progress": 0.5},
                  ("color", "depth", "motion", "history", "jitter"), 1))
    cases.append(("better and jitter-aware",
                  {"val_l1": 0.015, "val_baseline_l1": 0.02, "drift": 0.002, "depth_ablation": 0.001,
                   "motion_ablation": 0.001, "history_ablation": 0.001, "jitter_ablation": 0.001,
                   "train_progress": 0.5},
                  ("color", "depth", "motion", "history", "jitter"), 0))
    problems = 0
    for name, numbers, inputs, expected in cases:
        found = check_gates(numbers, inputs=inputs)
        if len(found) == expected:
            print("  %-32s %d gate(s) failed, as expected" % (name, len(found)))
        else:
            print("  %-32s expected %d failures, got %d - the gates are wrong"
                  % (name, expected, len(found)))
            problems += 1
        for reason in found:
            print("      - %s" % reason)

    # The P3 loss and schedule functions have closed forms, pinned here so a lever is not adopted on the
    # strength of a loss that does not actually compute what its name claims.
    identical = torch.zeros(1, 3, 32, 32)
    loss_cases = [
        ("l1 of identical images is zero", abs(float(compute_loss("l1", identical, identical, 0.1))) < 1e-9),
        ("charbonnier of identical images is its eps floor (the smooth-L1 property)",
         abs(float(compute_loss("charbonnier", identical, identical, 0.1)) - 1e-3) < 1e-9),
        ("ssim term of identical images is zero", abs(float(ssim_loss(identical, identical))) < 1e-9),
        ("l1ssim of identical images is zero",
         abs(float(compute_loss("l1ssim", identical, identical, 0.1))) < 1e-9),
        ("cosine anneals to the floor by the last epoch",
         abs(lr_for_epoch(60, 60, 0.002, 5, "cosine") - 0.002 * 1e-3) < 1e-12),
        ("linear warmup ramps to base at the warmup edge",
         abs(lr_for_epoch(5, 60, 0.002, 5, "linear-warmup") - 0.002) < 1e-12),
        ("linear warmup holds after the warmup edge",
         abs(lr_for_epoch(6, 60, 0.002, 5, "linear-warmup") - 0.002) < 1e-12),
    ]
    # De-jitter. The sign and the inversion are the whole point, so they are pinned against a signal where
    # interpolation blur cannot hide a sign error: a linear ramp shifted by a known amount. A sinusoid would
    # not do - de-jittering costs some sharpness to a second bilinear pass, and that softening can mask a
    # wrong sign, which is exactly the bug these checks exist to prevent.
    ramp_height = ramp_width = 64
    ramp_y, ramp_x = torch.meshgrid(torch.arange(ramp_height, dtype=torch.float32),
                                    torch.arange(ramp_width, dtype=torch.float32), indexing="ij")
    ramp = ramp_x[None, None]

    def ramp_grid(offset_x, offset_y):
        # The captured frame, built the way the capture builds it: a positive offset moves the content,
        # so the stored frame samples the scene at (x - offset). Building it the other way was the bug
        # this self-test used to encode.
        grid_y, grid_x = torch.meshgrid(torch.arange(ramp_height, dtype=torch.float32),
                                        torch.arange(ramp_width, dtype=torch.float32), indexing="ij")
        grid = torch.stack(((2.0 * (grid_x - offset_x) + 1.0) / ramp_width - 1.0,
                            (2.0 * (grid_y - offset_y) + 1.0) / ramp_height - 1.0), dim=-1)[None]
        return torch.nn.functional.grid_sample(ramp, grid, mode="bilinear", padding_mode="border",
                                               align_corners=False)

    def jitter_plane(x, y):
        plane = torch.zeros(1, 2, ramp_height, ramp_width)
        plane[:, 0] = x
        plane[:, 1] = y
        return plane

    captured_ramp = ramp_grid(0.3, 0.2)
    correct = float((dejitter(captured_ramp, jitter_plane(0.3, 0.2)) - ramp).abs().mean())
    wrong = float((dejitter(captured_ramp, jitter_plane(-0.3, -0.2)) - ramp).abs().mean())
    uncorrected = float((captured_ramp - ramp).abs().mean())
    loss_cases += [
        ("de-jitter with zero jitter is the identity",
         torch.equal(dejitter(ramp, jitter_plane(0.0, 0.0)), ramp)),
        ("de-jitter recovers a known shift (%.4f vs %.4f)" % (correct, uncorrected),
         correct < uncorrected * 0.1),
        ("the opposite sign is worse than no correction (%.4f vs %.4f)" % (wrong, uncorrected),
         wrong > uncorrected),
        ("de-jitter keeps the frame the same size",
         dejitter(ramp, jitter_plane(0.3, 0.2)).shape == ramp.shape),
    ]

    # Every consumed input must actually be reachable by the ablation harness. A name missing from `measure()`
    # makes its ablation compare two identical forward passes and return exactly 0.0, which reads as "the model
    # ignores this input" and sent the earlier investigation after the architecture when the harness had simply
    # never zeroed the tensor. Pinned by asking a jitter-consuming model to move when the harness zeroes jitter.
    probe = Upscaler(4, 2, 2, 2, 4, inputs=("color", "motion", "history", "jitter", "validity")).eval()
    # The output convolution is zero-initialised so an untrained model is exactly the bilinear baseline, which
    # makes the residual branch identically zero at init. Every input that only feeds the residual would then
    # measure exactly 0.0 no matter whether the harness can reach it - the test would pass for the wrong reason
    # or fail for a misleading one. Perturbing the weights wakes the branch so the probe tests the harness
    # rather than the initialisation.
    with torch.no_grad():
        for parameter in probe.parameters():
            parameter.add_(torch.randn_like(parameter) * 0.05)
    probe_batch = {
        "color": torch.rand(2, 3, 16, 16),
        "motion": torch.rand(2, 2, 16, 16),
        "history": torch.rand(2, 3, 16, 16),
        "jitter": torch.full((2, 2, 16, 16), 0.25),
        "validity": torch.full((2, 1, 16, 16), 0.75),
        "target": torch.rand(2, 3, 32, 32),
    }
    loss_cases += [
        ("the ablation harness can zero every consumed input",
         all(float((measure(probe, probe_batch)["output"]
                    - measure(probe, probe_batch, zero=name)["output"]).abs().mean()) > 0.0
             for name in ("depth", "motion", "history", "jitter", "validity")
             if name in probe.inputs)),
    ]

    for name, ok in loss_cases:
        print("  %-44s %s" % (name, "OK" if ok else "FAIL"))
        problems += 0 if ok else 1

    # The export's example tensors have to reach the model's own forward signature by name. Passing them in
    # `inputs` order instead bound them to parameter position, so a color+motion+history model fed its
    # 3-channel history tensor into the 2-channel motion convolution and could not be exported at all. Every
    # model exported before this was colour-only, so the case could not arise; it is pinned here for the
    # input set that does use it, and it checks the traced graph's declared inputs rather than only that the
    # call returned, because the old bug failed loudly at runtime and a graph that merely exported would be
    # just as wrong.
    try:
        import onnx
        temporal = Upscaler(4, 4, 4, 4, inputs=("color", "motion", "history")).eval()
        path = os.path.join(tempfile.mkdtemp(), "selftest_export.onnx")
        export_onnx(temporal, path, 8, temporal.inputs)
        declared = [entry.name for entry in onnx.load(path).graph.input]
        expected = ["color", "motion", "history"]
        check_ok = declared == expected
        print("  %-44s %s" % ("export binds inputs by name, not position",
                              "OK (%s)" % ", ".join(declared) if check_ok else "FAIL %s" % declared))
        problems += 0 if check_ok else 1

        # And the graph must reproduce the module, which is what a wrong binding silently breaks: the history
        # tensor is what reaches the motion convolution, so the output differs from the module's own.
        import onnxruntime
        session = onnxruntime.InferenceSession(path, providers=["CPUExecutionProvider"])
        probe = {"color": torch.rand(1, 3, 8, 8), "motion": torch.rand(1, 2, 8, 8),
                 "history": torch.rand(1, 3, 8, 8)}
        with torch.no_grad():
            reference = temporal(probe["color"], None, probe["motion"], probe["history"])
        produced = session.run([OUTPUT_NAME], {k: v.numpy() for k, v in probe.items()})[0]
        difference = float(np.abs(produced - reference.numpy()).max())
        check_ok = difference < 1e-5
        print("  %-44s %s" % ("exported graph reproduces the module (max %.1e)" % difference,
                              "OK" if check_ok else "FAIL"))
        problems += 0 if check_ok else 1

        # The trace must also survive the settings a real run uses. --deterministic rewrites F.interpolate
        # into a decomposition that mixes devices, so tracing a CUDA model with it on died in the middle of
        # exporting a model that had trained and passed every gate. The export now traces on the CPU; this
        # pins that under the same flag, on a CUDA model when one is present.
        # torch.use_deterministic_algorithms returns None, so the previous setting is read from the flag rather
        # than from the call's result - passing that None back is a TypeError, which is how this check first
        # failed.
        previous = torch.are_deterministic_algorithms_enabled()
        torch.use_deterministic_algorithms(True, warn_only=True)
        try:
            device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
            cuda_model = Upscaler(4, 4, 4, 4, inputs=("color", "motion", "history")).to(device).eval()
            traced = os.path.join(tempfile.mkdtemp(), "selftest_export_deterministic.onnx")
            export_onnx(cuda_model, traced, 8, cuda_model.inputs)
            check_ok = os.path.exists(traced)
            print("  %-44s %s" % ("export traces under --deterministic settings (%s)" % device.type,
                                  "OK" if check_ok else "FAIL"))
            problems += 0 if check_ok else 1
            # And the weights are handed back on the device they came from, or every later measurement in
            # the run would silently be comparing a CPU model against CUDA tensors.
            check_ok = next(cuda_model.parameters()).device.type == device.type
            print("  %-44s %s" % ("export returns the model to its own device",
                                  "OK" if check_ok else "FAIL"))
            problems += 0 if check_ok else 1

            # And the verification step itself, which is the check on the export. It splatted the batch in
            # input-set order into the forward signature, so for this same model it fed history into the
            # motion convolution and crashed instead of verifying - the step meant to catch a bad export was
            # the thing that died. Run it here with the exact shape a run hands it.
            verification = verify_export(cuda_model, traced, {
                "color": torch.rand(1, 3, 8, 8, device=device),
                "motion": torch.rand(1, 2, 8, 8, device=device),
                "history": torch.rand(1, 3, 8, 8, device=device)})
            check_ok = verification.get("checked") and verification.get("max_abs_difference", 1.0) < 1e-5
            print("  %-44s %s" % ("verify_export runs on a multi-input model",
                                  "OK (max %.1e)" % verification.get("max_abs_difference", float("nan"))
                                  if check_ok else "FAIL %s" % verification))
            problems += 0 if check_ok else 1
        finally:
            torch.use_deterministic_algorithms(previous, warn_only=True)
    except ImportError as missing:
        # onnx is a documented dependency of the export, but the numeric self-tests above do not need it, so a
        # runner without it loses these two checks rather than the whole suite.
        print("  %-44s SKIPPED (%s)" % ("export binds inputs by name, not position", missing))

    # Detail weighting: a flat target has no detail, so the weight must be uniform (no rebalancing); a
    # textured target concentrates weight on edges; and the weight always has mean ~1 so it rebalances, not
    # rescales.
    flat_target = torch.full((2, 3, 16, 16), 0.4)
    w_flat = detail_weight_map(flat_target, 0.5)
    check_ok = abs(float(w_flat.max() - w_flat.min())) < 1e-6
    print("  %-44s %s" % ("detail weight of a flat target is uniform (no detail to rebalance)", "OK" if check_ok else "FAIL"))
    problems += 0 if check_ok else 1

    xx, yy = torch.meshgrid(torch.arange(16), torch.arange(16), indexing="ij")
    checker = ((xx + yy) % 2).float().repeat(2, 3, 1, 1)
    w_checker = detail_weight_map(checker, 0.5)
    check_ok = float(w_checker.max()) > float(w_checker.min())
    print("  %-44s %s" % ("detail weight concentrates on edges of a textured target", "OK" if check_ok else "FAIL"))
    problems += 0 if check_ok else 1

    rng_t = torch.rand(2, 3, 32, 32)
    w_rng = detail_weight_map(rng_t, 0.5)
    check_ok = abs(float(w_rng.mean()) - 1.0) < 0.01
    print("  %-44s %s" % ("detail weight has mean ~1 on a textured target", "OK" if check_ok else "FAIL"))
    problems += 0 if check_ok else 1

    # Lazy loading against eager loading, on real pair files rather than on tensors in memory: the claim is
    # that --lazy changes *when* a pair is read and nothing else, and the file is what the lazy path reads.
    workdir = tempfile.mkdtemp(prefix="nrr-selftest-")
    pairs_dir = os.path.join(workdir, "pairs")
    os.makedirs(pairs_dir)
    rng = np.random.RandomState(7)
    files = []
    for index in range(3):
        path = os.path.join(pairs_dir, "pair_%03d.npz" % index)
        np.savez(path,
                 input=rng.rand(16, 12, 3).astype(np.float32),
                 depth=rng.rand(16, 12).astype(np.float32),
                 motion=rng.rand(16, 12, 2).astype(np.float32),
                 target=rng.rand(32, 24, 3).astype(np.float32),
                 history=rng.rand(16, 12, 3).astype(np.float32),
                 validity=rng.rand(16, 12).astype(np.float32),
                 jitter=np.array([0.25, -0.5], np.float32))
        files.append(path)
    with open(os.path.join(pairs_dir, "manifest.json"), "w", encoding="utf-8", newline="\n") as handle:
        json.dump({"pairs": [{"file": os.path.basename(path), "split": "val" if index == 1 else "train"}
                             for index, path in enumerate(files)]}, handle)
    _, eager = load_dataset(pairs_dir)
    _, lazily = load_dataset(pairs_dir, lazy=True)
    keys = list(eager["train"].keys)
    positions = torch.tensor([1, 0], dtype=torch.long)
    eager_batch = eager["train"].batch(positions)
    lazy_batch = lazily["train"].batch(positions)
    check_ok = (lazily["train"].keys == keys
                and keys == ["color", "depth", "motion", "target", "history", "jitter", "validity"]
                and lazily["train"].count == eager["train"].count
                and lazily["sizes"] == eager["sizes"]
                and all(bool(torch.equal(lazy_batch[key], eager_batch[key])) for key in keys))
    print("  %-44s %s" % ("lazy loading matches eager pair for pair",
                          "OK" if check_ok else "FAIL"))
    problems += 0 if check_ok else 1

    # The zeroed-input ablation has to mean the same thing on both loaders, or an --lazy ablation run would not
    # be comparable to the eager run it is quoted against.
    eager["train"].zero("motion")
    lazily["train"].zero("motion")
    eager_zeroed = eager["train"].batch(positions)["motion"]
    lazy_zeroed = lazily["train"].batch(positions)["motion"]
    check_ok = bool(torch.equal(eager_zeroed, lazy_zeroed)) and float(eager_zeroed.abs().max()) == 0.0
    print("  %-44s %s" % ("zeroing an input agrees between the two loaders", "OK" if check_ok else "FAIL"))
    problems += 0 if check_ok else 1

    with np.load(files[0]) as handle:
        sample = pair_from_npz(handle)
    # The target is rebuilt as a nearest-neighbour upsample of the input, so "the crop is aligned" becomes a
    # property that can be checked rather than asserted: if the two windows were taken from different parts of
    # the image, the equality below fails.
    sample["target"] = sample["color"].repeat_interleave(2, dim=-2).repeat_interleave(2, dim=-1)
    flat = {"flip_h": False, "flip_v": False, "crop_h": 8, "crop_w": 6, "offset_y": 3, "offset_x": 2}
    cropped = augment_sample(sample, flat, 2, 2)
    check_ok = (tuple(cropped["color"].shape[-2:]) == (8, 6)
                and tuple(cropped["target"].shape[-2:]) == (16, 12)
                and bool(torch.allclose(cropped["target"],
                                        sample["color"][..., 3:11, 2:8].repeat_interleave(2, dim=-2)
                                        .repeat_interleave(2, dim=-1)))
                and bool(torch.allclose(cropped["motion"], sample["motion"][..., 3:11, 2:8]))
                # Jitter is cropped like any other input. Its values are unchanged - it is one offset spread
                # over the frame - but its *shape* has to follow the input, because the model concatenates the
                # two grids.
                and bool(torch.allclose(cropped["jitter"], sample["jitter"][..., 3:11, 2:8]))
                and tuple(cropped["jitter"].shape[-2:]) == tuple(cropped["color"].shape[-2:])
                and bool(torch.allclose(cropped["history"], sample["history"][..., 3:11, 2:8])))
    print("  %-44s %s" % ("a crop keeps the target on the same part of the image",
                          "OK" if check_ok else "FAIL"))
    problems += 0 if check_ok else 1

    # The mirrors. This is the part of augmentation that is easy to get wrong and silently harmful: a mirrored
    # pair whose motion was not also mirrored has motion pointing the wrong way, which teaches the model
    # something false about its own input. Both axes are checked separately because they negate different
    # components, and each also has to leave the other one alone.
    whole = {"flip_h": True, "flip_v": False, "crop_h": 16, "crop_w": 12, "offset_y": 0, "offset_x": 0}
    sideways = augment_sample(sample, whole, 2, 2)
    check_ok = (bool(torch.equal(sideways["color"], torch.flip(sample["color"], dims=(-1,))))
                and bool(torch.allclose(sideways["motion"][:, 0:1],
                                        -torch.flip(sample["motion"][:, 0:1], dims=(-1,))))
                and bool(torch.allclose(sideways["motion"][:, 1:2],
                                        torch.flip(sample["motion"][:, 1:2], dims=(-1,))))
                and bool(torch.allclose(sideways["jitter"][:, 0:1], -sample["jitter"][:, 0:1]))
                and bool(torch.allclose(sideways["jitter"][:, 1:2], sample["jitter"][:, 1:2])))
    print("  %-44s %s" % ("a horizontal mirror negates motion and jitter x only",
                          "OK" if check_ok else "FAIL"))
    problems += 0 if check_ok else 1

    upright = {"flip_h": False, "flip_v": True, "crop_h": 16, "crop_w": 12, "offset_y": 0, "offset_x": 0}
    vertical = augment_sample(sample, upright, 2, 2)
    check_ok = (bool(torch.equal(vertical["color"], torch.flip(sample["color"], dims=(-2,))))
                and bool(torch.allclose(vertical["motion"][:, 1:2],
                                        -torch.flip(sample["motion"][:, 1:2], dims=(-2,))))
                and bool(torch.allclose(vertical["motion"][:, 0:1],
                                        torch.flip(sample["motion"][:, 0:1], dims=(-2,))))
                and bool(torch.allclose(vertical["jitter"][:, 1:2], -sample["jitter"][:, 1:2]))
                and bool(torch.allclose(vertical["jitter"][:, 0:1], sample["jitter"][:, 0:1])))
    print("  %-44s %s" % ("a vertical mirror negates motion and jitter y only", "OK" if check_ok else "FAIL"))
    problems += 0 if check_ok else 1

    # --deterministic has to pin an augmented run too. If the draw were not seeded, the augmentation arguments
    # would make a seed stop meaning anything, which is the exact failure the flag exists to prevent.
    batch = eager["train"].batch(torch.tensor([0, 1], dtype=torch.long))
    drawn = [augment_batch(batch, (8, 12), True, torch.Generator().manual_seed(11)) for _ in range(2)]
    check_ok = all(bool(torch.equal(drawn[0][key], drawn[1][key])) for key in drawn[0])
    # One batch, one crop tier. This is the regression test for a bug this file actually had: the crop size was
    # drawn per sample, so a batch whose samples drew 96 and 112 could not be stacked into the tensor a
    # convolution consumes, and the run died inside torch.cat. The loop is over seeds because the bug only
    # appears when two samples in the same batch draw different sizes, and the assertion is on the invariant
    # rather than on one expected shape, because *which* tier a batch gets is the random part: every
    # low-resolution input must end up on the colour input's grid, and the target on the grid above it.
    allowed = {(8, 6), (12, 9)}    # --crop-sizes 8 or 12 on a 16x12 frame, width following the aspect ratio
    check_ok = True
    for seed in range(8):
        tier = augment_batch(batch, (8, 12), True, torch.Generator().manual_seed(seed))
        grid = tuple(tier["color"].shape[-2:])
        if grid not in allowed or tuple(tier["target"].shape[-2:]) != (grid[0] * 2, grid[1] * 2):
            check_ok = False
        for key, value in tier.items():
            if key != "target" and tuple(value.shape[-2:]) != grid:
                check_ok = False
    print("  %-44s %s" % ("a cropped batch stacks at every tier and seed", "OK" if check_ok else "FAIL"))
    problems += 0 if check_ok else 1
    return 1 if problems else 0


def main(argv):
    parser = argparse.ArgumentParser(description="Train the in-house NRR upscaler.")
    parser.add_argument("--data", default="models/training-data/v1")
    parser.add_argument("--out", default="models/nrr_upscaler_trained.onnx")
    parser.add_argument("--epochs", type=int, default=60)
    parser.add_argument("--batch-size", type=int, default=4)
    parser.add_argument("--measure-batch", type=int, default=32,
                        help="forward-pass batch size for the held-out measurement. The val split is one "
                             "tensor, and a wide model (64 channels) can need more memory for one 400-image "
                             "forward than the card has; slicing it is exact because the model has no batch "
                             "statistics, so it is a memory fix and not a method change")
    parser.add_argument("--channels", type=int, default=32,
                        help="network width; 64 gives roughly 0.27M parameters")
    parser.add_argument("--depth-channels", type=int, default=8)
    parser.add_argument("--motion-channels", type=int, default=8)
    parser.add_argument("--history-channels", type=int, default=8)
    parser.add_argument("--jitter-channels", type=int, default=8,
                        help="width of the branch that consumes the frame's sub-pixel sampling offset; "
                             "only built when 'jitter' is in --inputs")
    parser.add_argument("--validity-channels", type=int, default=8,
                        help="width of the branch that consumes the capture's trust mask on the history it "
                             "carries; only built when 'validity' is in --inputs")
    parser.add_argument("--inputs", default="depth,motion",
                        help="comma-separated inputs besides color, which is always first: a subset of "
                             "depth,motion,history,jitter,validity. This is the comparison - a model given "
                             "history is a different model from one that is not, and the run reports which is "
                             "better")
    parser.add_argument("--learning-rate", type=float, default=2e-3)
    parser.add_argument("--loss", default="l1", choices=("l1", "charbonnier", "l1ssim"),
                        help="P3 lever 2: the training loss. l1 is the measured gate; charbonnier and "
                             "l1ssim are tried against the same bars, never assumed better")
    parser.add_argument("--ssim-weight", type=float, default=0.1,
                        help="weight of the SSIM term in --loss l1ssim")
    parser.add_argument("--detail-weight", type=float, default=0.0,
                        help="P3 lever 4: strength of the per-pixel detail weighting, which rebalances the "
                             "loss toward high-frequency regions of the target (0 = off)")
    parser.add_argument("--lr-schedule", default="linear-warmup",
                        choices=("linear-warmup", "cosine"),
                        help="P3 lever 3: linear-warmup holds the warmup peak; cosine anneals to 1e-3 of it")
    parser.add_argument("--warmup-epochs", type=int, default=5,
                        help="linear learning-rate warmup. Added because 2 of 10 seeds failed early - one "
                             "froze with the output at the baseline, one learned only 2.9% better than it - "
                             "and both are the pathology a warmup addresses on a zero-initialised head")
    parser.add_argument("--seed", type=int, default=20260930)
    parser.add_argument("--size", type=int, default=64,
                        help="the input size the model was trained at, used for the export example")
    parser.add_argument("--device", default="auto", choices=("auto", "cpu", "cuda"),
                        help="auto uses the GPU whenever torch can provide one; cuda refuses to run "
                             "on the CPU instead of pretending")
    parser.add_argument("--deterministic", action="store_true",
                        help="make a seed pin a result: cuDNN autotuning off and deterministic kernels "
                             "requested. Without it two runs of the same seed diverge measurably on this "
                             "workload, because autotuning picks convolution algorithms by timing them. "
                             "Slower, and the honest choice for any run whose number will be compared")
    parser.add_argument("--zero-input", default="none",
                        choices=("none", "depth", "motion", "history", "jitter", "validity"),
                        help="ablation run: zero this input for training and validation, to measure "
                             "what it is worth")
    parser.add_argument("--lazy", action="store_true",
                        help="read the training split's npz files per batch instead of concatenating the "
                             "whole split into memory first. Same pairs, the same order and the same numbers; "
                             "the difference is that a dataset larger than RAM can be trained on at all. "
                             "Validation is still loaded whole, because the held-out number forwards every "
                             "val pair anyway")
    parser.add_argument("--augment-flip", action="store_true",
                        help="mirror each training sample horizontally and/or vertically at random, negating "
                             "the motion and jitter component that points along the mirrored axis so the pair "
                             "stays internally consistent. Off by default: every number recorded in this "
                             "repository was produced without it")
    parser.add_argument("--crop-sizes", default="",
                        help="comma-separated input heights to crop training samples to, one drawn per "
                             "sample, which is the multi-scale lever - a model trained at a single frame size "
                             "has seen one tier of it. Width follows the frame's aspect ratio and the target "
                             "is cropped to the matching window. Empty (the default) trains on whole frames")
    parser.add_argument("--self-test", action="store_true")
    args = parser.parse_args(argv[1:])
    if args.self_test:
        return self_test()
    torch.set_num_threads(os.cpu_count() or 4)
    return run(args, lambda message: print(message, flush=True))


def conv(in_channels, out_channels, kernel=3):
    return nn.Conv2d(in_channels, out_channels, kernel, padding=kernel // 2)


def dejitter(color, jitter):
    """Resample a captured low-resolution frame back onto the grid it was *not* sampled on.

    A jittered capture renders the scene shifted by `-jitter` pixels, so the stored frame satisfies
    `input(x) = scene(x - jitter)`. Recovering `scene` therefore means sampling the input at
    `x + jitter`, which is what this does with a bilinear grid - a true resampling of the pixels, not an
    extra tensor the network is free to ignore.

    The sign here is the data's, not a choice. It was verified three ways against the captured pixels
    (tools/aa_samples_probe.py: simulating both hypotheses from the high-resolution target, applying the
    correction each way and scoring edge error, and the capture's own one-pixel render self-test): a
    positive recorded jitter displaces the frame's *content* by +j, so the correction runs the other way
    from the recorded value. The previous direction doubled the misalignment instead of removing it, and
    every model trained before this change was trained on frames that were left shifted by 2j.

    This exists because of a measured failure. Feeding the offset as a conv input gave the network a branch
    it could give zero weight: the jitter ablation came back at exactly 0.00000 on both seeds while motion
    and history in the same model were clearly used. The reason is architectural, not informational - the
    offset is constant across the image, so a convolution over a broadcast plane can only express a global
    bias, and exploiting the offset would need the network to *shift its resampling*, which a conv stack
    feeding a fixed bilinear skip does not parameterise. Making the resampling itself depend on the offset
    removes the choice: with jitter zeroed the output geometry genuinely changes.

    `padding_mode="border"` rather than zeros, because the shifted sample can fall outside the frame at the
    edges and a black border there would be an artefact of the correction, not of the scene.
    """
    _, _, height, width = color.shape
    ys = torch.arange(height, device=color.device, dtype=color.dtype)
    xs = torch.arange(width, device=color.device, dtype=color.dtype)
    # jitter arrives as the (B,2,H,W) plane the loader broadcast, and is read per-pixel rather than
    # per-frame so this stays correct if a future capture jitters within a frame. The unsqueezed axes line
    # the x and y coordinate planes up against it, and the leading axis is dropped so grid_sample gets the
    # (B,H,W,2) it wants.
    offset_x = jitter[:, 0].unsqueeze(1)                 # (B,1,H,W)
    offset_y = jitter[:, 1].unsqueeze(1)                 # (B,1,H,W)
    u = xs.view(1, 1, 1, width) + offset_x
    v = ys.view(1, 1, height, 1) + offset_y
    grid = torch.stack(((2.0 * u + 1.0) / width - 1.0,
                        (2.0 * v + 1.0) / height - 1.0), dim=-1).squeeze(1)
    return torch.nn.functional.grid_sample(color, grid, mode="bilinear", padding_mode="border",
                                           align_corners=False)


class ResidualBlock(nn.Module):
    """Two 3x3 convolutions and an add, which is the refinement stage architecture.md describes.

    Leaky activations, not ReLU, and the reason is measured rather than stylistic. Five of eight stage-4
    runs sat at exactly the untrained-model loss: the output convolution is zero-initialised (so the
    untrained model is exactly the bilinear baseline), which means the gradient reaching every upstream
    layer is W_out^T * grad and is exactly zero until that weight moves. A plain ReLU that an early Adam
    step drives negative across a whole channel then zeroes the features feeding that convolution, so
    grad_W_out = grad * features is zero too, and the network freezes in an absorbing state it cannot
    leave. A leaking activation keeps those features non-zero, so the weight keeps moving and the rest of
    the network keeps its gradient path."""

    def __init__(self, channels):
        super().__init__()
        self.body = nn.Sequential(conv(channels, channels), nn.LeakyReLU(0.01, inplace=True),
                                  conv(channels, channels))

    def forward(self, x):
        return torch.nn.functional.leaky_relu(x + self.body(x), 0.01)


class Upscaler(nn.Module):
    """A reduced version of models/architecture.md - the same stages at smaller widths, because the
    pairs are 2x at these sizes and a 2.5M-parameter network would be neither trainable here nor
    measurable against a fixture. `channels=64` gives roughly 0.27M parameters.

    `inputs` names which tensors this model consumes, and it is a parameter rather than a constant because
    that is the question: a model given history is a different model from one given only colour, and which
    of them is better has to be run rather than assumed. A branch is built only for an input in the set, so
    a colour-only model has no depth, motion or history weights at all - the comparison is between models,
    not between a model and its own zeroed inputs."""

    def __init__(self, channels=32, depth_channels=8, motion_channels=8, history_channels=8,
                 jitter_channels=8, inputs=("color", "depth", "motion"), validity_channels=8):
        super().__init__()
        self.inputs = tuple(inputs)
        # Leaky throughout, for the same measured reason as ResidualBlock: a feature map that is exactly
        # zero anywhere upstream of the zero-initialised output convolution cuts the only gradient path the
        # network has.
        self.feature = nn.Sequential(conv(3, channels), nn.LeakyReLU(0.01, inplace=True),
                                     conv(channels, channels), nn.LeakyReLU(0.01, inplace=True))
        fused = channels
        if "depth" in self.inputs:
            self.depth = conv(1, depth_channels)
            fused += depth_channels
        if "motion" in self.inputs:
            self.motion = conv(2, motion_channels)
            fused += motion_channels
        if "history" in self.inputs:
            self.history = conv(3, history_channels)
            fused += history_channels
        if "jitter" in self.inputs:
            # Two channels: the frame's sub-pixel sampling offset. Constant across the image, but a
            # convolution over the plane is what lets the network use it as a global conditioning signal
            # rather than only as something appended to a feature map.
            self.jitter = conv(2, jitter_channels)
            fused += jitter_channels
        if "validity" in self.inputs:
            # One channel: the capture's own mask on the history, so the network does not have to infer from
            # pixels whether a history sample is a reprojection artefact. A temporal model that has to learn
            # disocclusion implicitly is what the first temporal arms measured badly.
            self.validity = conv(1, validity_channels)
            fused += validity_channels
        self.fusion = conv(fused, channels * 4)
        self.shuffle = nn.PixelShuffle(2)
        self.refine = nn.Sequential(conv(channels, channels), nn.LeakyReLU(0.01, inplace=True))
        self.block1 = ResidualBlock(channels)
        self.block2 = ResidualBlock(channels)
        self.output = conv(channels, 3)
        self.skip = nn.Upsample(scale_factor=2, mode="bilinear", align_corners=False)
        # Start as the baseline: a zeroed output convolution plus the skip means the untrained model is
        # exactly the bilinear upsample, so any improvement measured later is something learned.
        nn.init.zeros_(self.output.weight)
        nn.init.zeros_(self.output.bias)

    def prepare(self, color, jitter=None):
        """The frame every later stage sees: de-jittered when the model consumes jitter.

        Called from both entry points rather than inside one of them, because training calls `residual()`
        directly (the loss is on the correction alone) while inference goes through `forward()`. Doing the
        correction in each would resample the frame twice on the inference path.
        """
        return dejitter(color, jitter) if "jitter" in self.inputs else color

    def residual(self, color, depth=None, motion=None, history=None, jitter=None, validity=None):
        """The correction alone, from the raw inputs. This is what training optimises (the bilinear skip
        carries the low frequencies, so the loss is on what the model adds), so it prepares the frame
        itself rather than assuming someone already did."""
        return self._residual_prepared(self.prepare(color, jitter), depth, motion, history, jitter, validity)

    def _residual_prepared(self, color, depth, motion, history, jitter, validity=None):
        features = self.feature(color)
        parts = [features]
        if "depth" in self.inputs:
            parts.append(self.depth(depth))
        if "motion" in self.inputs:
            parts.append(self.motion(motion))
        if "history" in self.inputs:
            parts.append(self.history(history))
        if "jitter" in self.inputs:
            parts.append(self.jitter(jitter))
        if "validity" in self.inputs:
            parts.append(self.validity(validity))
        features = self.refine(self.shuffle(self.fusion(torch.cat(parts, dim=1))))
        features = self.block2(self.block1(features))
        return self.output(features)

    def forward(self, color, depth=None, motion=None, history=None, jitter=None, validity=None):
        corrected = self.prepare(color, jitter)
        return self.skip(corrected) + self._residual_prepared(corrected, depth, motion, history, jitter,
                                                              validity)


def baseline_upscale(color):
    """The thing the model has to beat, computed exactly the way the model's own skip does."""
    return torch.nn.functional.interpolate(color, scale_factor=2, mode="bilinear", align_corners=False)


def _gaussian_line(window_size, sigma):
    coords = torch.arange(window_size, dtype=torch.float32) - (window_size - 1) / 2.0
    line = torch.exp(-(coords ** 2) / (2.0 * sigma * sigma))
    return line / line.sum()


def ssim_loss(x, y, window_size=11):
    """Differentiable (1 - SSIM), averaged over channels and pixels, for the `l1ssim` lever.

    Uses the same C1/C2 as the numpy and C++ SSIM ((0.01*255)^2 and (0.03*255)^2 on [0,1] inputs are
    0.0001 and 0.0009), so an identical pair scores exactly zero and two uniform images reduce to the same
    luminance term quality_metrics.py reports. Pinned by the self-test, not by assertion alone."""
    channels = x.shape[1]
    line = _gaussian_line(window_size, 1.5).unsqueeze(1)
    kernel = (line @ line.t()).float().unsqueeze(0).unsqueeze(0)
    window = kernel.expand(channels, 1, window_size, window_size).contiguous().to(x.device)
    pad = window_size // 2
    mu_x = torch.nn.functional.conv2d(x, window, padding=pad, groups=channels)
    mu_y = torch.nn.functional.conv2d(y, window, padding=pad, groups=channels)
    mu_xy = mu_x * mu_y
    var_x = torch.nn.functional.conv2d(x * x, window, padding=pad, groups=channels) - mu_x ** 2
    var_y = torch.nn.functional.conv2d(y * y, window, padding=pad, groups=channels) - mu_y ** 2
    cov = torch.nn.functional.conv2d(x * y, window, padding=pad, groups=channels) - mu_xy
    c1 = 0.0001
    c2 = 0.0009
    ssim_map = ((2.0 * mu_xy + c1) * (2.0 * cov + c2)) / \
               ((mu_x ** 2 + mu_y ** 2 + c1) * (var_x + var_y + c2))
    return 1.0 - ssim_map.mean()


def compute_loss(name, prediction, truth, ssim_weight, weight=None, full_output=None, full_target=None):
    """The training loss. L1 is the measured gate; Charbonnier and L1+SSIM are the P3 levers, each tried
    against the same bars rather than assumed better. `weight`, when given, is a per-pixel (B,1,H,W) map
    with mean 1 that rebalances the loss toward high-frequency regions (the detail-weighting lever).

    The L1/Charbonnier term is on the residual (the correction the skip cannot supply), as it always was.
    The SSIM term must be on the *full image* (`full_output` = skip + residual, `full_target`), because SSIM
    of a residual is meaningless - the first l1ssim run computed it on the residual and the model learned
    nothing (2.9% progress, still at the baseline), which is a measurement of the bug, not of the lever."""
    if weight is not None:
        diff = (prediction - truth).abs()
        if name == "charbonnier":
            eps = 1e-3
            return (weight * torch.sqrt((prediction - truth) ** 2 + eps ** 2)).mean()
        if name == "l1ssim":
            ssim_term = ssim_loss(full_output, full_target) if full_output is not None else ssim_loss(prediction, truth)
            return (weight * diff).mean() + ssim_weight * ssim_term
        return (weight * diff).mean()
    if name == "charbonnier":
        eps = 1e-3
        return torch.sqrt((prediction - truth) ** 2 + eps ** 2).mean()
    if name == "l1ssim":
        ssim_term = ssim_loss(full_output, full_target) if full_output is not None else ssim_loss(prediction, truth)
        return torch.nn.functional.l1_loss(prediction, truth) + ssim_weight * ssim_term
    return torch.nn.functional.l1_loss(prediction, truth)


def detail_weight_map(target, strength):
    """Per-pixel loss weight emphasising high-frequency regions of the target, for the detail-weighting lever.

    The weight is 1 + strength * (laplacian / mean(laplacian) - 1), so it has mean exactly 1.0 - the lever
    rebalances the loss toward where the target has detail (foliage, edges) rather than rescaling it. The
    Laplacian is the same 3x3 high-pass the packer's `_detail()` uses as a per-image scalar, here applied
    per pixel so the loss can care about *where* the detail is, not just how much of it there is."""
    grey = target[:, 0] * np.float32(0.299) + target[:, 1] * np.float32(0.587) + target[:, 2] * np.float32(0.114)
    kernel = torch.tensor([[0.0, 1.0, 0.0], [1.0, -4.0, 1.0], [0.0, 1.0, 0.0]],
                          dtype=target.dtype, device=target.device).view(1, 1, 3, 3)
    grey_padded = torch.nn.functional.pad(grey.unsqueeze(1), (1, 1, 1, 1), mode="replicate")
    lap = torch.abs(torch.nn.functional.conv2d(grey_padded, kernel))
    lap_mean = lap.mean(dim=(1, 2), keepdim=True) + 1e-6
    return 1.0 + strength * (lap / lap_mean - 1.0)


def lr_for_epoch(epoch, epochs, base, warmup_epochs, schedule):
    """The learning rate for an epoch. The linear warmup is what removed the one-in-five early-failure rate;
    cosine is the P3 lever that anneals to base * 1e-3 over the run instead of holding the warmup peak.
    Named `lr_for_epoch` rather than `learning_rate` so the float parameter of the same name in train() does
    not shadow it."""
    if schedule == "cosine":
        progress = (epoch - 1) / max(epochs - 1, 1)
        floor = 1e-3
        factor = floor + (1.0 - floor) * 0.5 * (1.0 + math.cos(math.pi * progress))
        if warmup_epochs > 0:
            factor *= min(1.0, float(epoch) / float(warmup_epochs))
        return base * factor
    ramp = min(1.0, float(epoch) / float(warmup_epochs)) if warmup_epochs > 0 else 1.0
    return base * ramp


def measure(model, batch, zero=None, chunk=32):
    """The numbers the gates use. `zero` names an input to replace with zeros, which is how each input's
    contribution is measured rather than assumed - including history, which is the whole point of the
    comparison this exists to settle.

    `chunk` caps the forward-pass batch size. The val split is one concatenated tensor, and a wide model
    (64 channels) needs more memory for a 400-image forward than the card has, so it is measured in slices.
    Slicing an inference-only forward over a model with no batch statistics is exact - the model is conv +
    activations, no BatchNorm - so the chunked number is the same number as the unchunked one. It is a
    memory fix, not a method change, and it is why a 64-channel run and a 32-channel run stay comparable."""
    with torch.no_grad():
        color = batch["color"]
        depth = batch.get("depth")
        motion = batch.get("motion")
        history = batch.get("history")
        jitter = batch.get("jitter")
        validity = batch.get("validity")
        if zero == "depth" and depth is not None:
            depth = torch.zeros_like(depth)
        if zero == "motion" and motion is not None:
            motion = torch.zeros_like(motion)
        if zero == "history" and history is not None:
            history = torch.zeros_like(history)
        # Jitter has to be listed here too, or the ablation compares two identical forward passes and reports
        # exactly zero by construction. That is not a weak signal, it is no measurement at all - and it is what
        # made the earlier architecture look like it ignored jitter when the harness had never tested it.
        if zero == "jitter" and jitter is not None:
            jitter = torch.zeros_like(jitter)
        # And the mask, for the same reason: an input the harness does not zero is an input the ablation
        # reports as unused without ever having withheld it.
        if zero == "validity" and validity is not None:
            validity = torch.zeros_like(validity)
        pieces = []
        for start in range(0, color.shape[0], chunk):
            end = start + chunk
            pieces.append(model(color[start:end],
                                depth[start:end] if depth is not None else None,
                                motion[start:end] if motion is not None else None,
                                history[start:end] if history is not None else None,
                                jitter[start:end] if jitter is not None else None,
                                validity[start:end] if validity is not None else None))
        output = torch.cat(pieces, dim=0)
        baseline = baseline_upscale(color)
        return {"l1": float(torch.nn.functional.l1_loss(output, batch["target"])),
                "baseline_l1": float(torch.nn.functional.l1_loss(baseline, batch["target"])),
                "drift": float((output - baseline).abs().mean()),
                "output": output,
                "baseline": baseline}


def train(dataset, inputs, epochs, batch_size, channels, depth_channels, motion_channels,
          history_channels, learning_rate, warmup_epochs, seed, device, log,
          loss_name="l1", ssim_weight=0.1, lr_schedule="linear-warmup", detail_weight=0.0,
          jitter_channels=8, validity_channels=8, augment=None):
    torch.manual_seed(seed)
    model = Upscaler(channels, depth_channels, motion_channels, history_channels,
                     jitter_channels, inputs=inputs, validity_channels=validity_channels).to(device)
    parameters = sum(p.numel() for p in model.parameters())
    log("  model: %d parameters, inputs=%s, channels=%d, batch=%d, epochs=%d, lr=%g, loss=%s, schedule=%s"
        % (parameters, ",".join(inputs), channels, batch_size, epochs, learning_rate,
           loss_name, lr_schedule))

    train_split = dataset["train"]
    count = train_split.count
    optimizer = torch.optim.Adam(model.parameters(), lr=learning_rate)
    generator = torch.Generator().manual_seed(seed)
    first_loss = last_loss = None
    first_plain = last_plain = None
    for epoch in range(1, epochs + 1):
        # Warmup. The output convolution starts at zero (which is what makes the untrained model exactly the
        # bilinear baseline), so the first Adam steps move a weight that has no history and Adam's step size
        # is largest exactly there. Ten seeds measured the consequence: two of them failed - one froze with
        # the output at 4e-05 of the baseline, one learned a real residual but only 2.9% better than it - and
        # both are early-training pathologies, which is what a warmup addresses. `lr_for_epoch()` carries the
        # warmup for both schedules so the lever changes the decay, not the protection.
        for group in optimizer.param_groups:
            group["lr"] = lr_for_epoch(epoch, epochs, learning_rate, warmup_epochs, lr_schedule)
        order = torch.randperm(count, generator=generator)
        model.train()
        total, plain_total, batches = 0.0, 0.0, 0
        for start in range(0, count, batch_size):
            batch = train_split.batch(order[start:start + batch_size])
            # Augmentation lives here, in the training loop, and not in the loader: a validation batch must
            # never be transformed, or the held-out number would be measured on pictures the model was allowed
            # to have seen mirrored.
            if augment is not None:
                batch = augment_batch(batch, augment["crop_sizes"], augment["flip"], generator)
            optimizer.zero_grad()
            # The loss is on the correction the skip cannot supply, not on the whole image: the skip
            # already carries the low frequencies, and weighting those equally would let the model coast
            # on the baseline and still report a small number.
            prediction = model.residual(batch["color"], batch.get("depth"), batch.get("motion"),
                                        batch.get("history"), batch.get("jitter"), batch.get("validity"))
            skip = baseline_upscale(batch["color"])
            truth = batch["target"] - skip
            weight = detail_weight_map(batch["target"], detail_weight) if detail_weight > 0.0 else None
            loss = compute_loss(loss_name, prediction, truth, ssim_weight, weight=weight,
                                full_output=skip + prediction, full_target=batch["target"])
            loss.backward()
            optimizer.step()
            total += float(loss)
            # The unweighted residual L1 is tracked alongside the objective, because the objective's scale
            # depends on the loss and the weight map: a detail-weighted run starts at 0.035 where a plain L1
            # run starts at 0.0148, so a "did training make progress" percentage computed on the objective is
            # not comparable between configurations. The progress *gate* is measured on this number instead,
            # which is the same quantity for every run and still catches a frozen one at ~0%.
            plain_total += float(torch.nn.functional.l1_loss(prediction, truth))
            batches += 1
        epoch_loss = total / max(batches, 1)
        epoch_plain = plain_total / max(batches, 1)
        if first_loss is None:
            first_loss, first_plain = epoch_loss, epoch_plain
        last_loss, last_plain = epoch_loss, epoch_plain
        if epoch == 1 or epoch == epochs or epoch % max(1, epochs // 5) == 0:
            log("  epoch %3d/%d  residual L1 %.5f (unweighted %.5f)" % (epoch, epochs, epoch_loss, epoch_plain))
    model.eval()
    return model, parameters, (first_loss or 0.0), (last_loss or 0.0), (first_plain or 0.0), (last_plain or 0.0)


# The entry point belongs at the end of the file: this guard sat above conv()/Upscaler()/train() for a
# while, so running the script called main() before those names existed and failed with a NameError that
# pointed at the wrong function.
if __name__ == "__main__":
    sys.exit(main(sys.argv))

